      "items": [
        {
          "id": "def-ip-unbounded-hilbert-moore-penrose-inverse",
          "kind": "definition",
          "title": "Hilbert-space Moore–Penrose inverse",
          "deps": [
            "def-bounded-linear-operator",
            "def-countable-choice",
            "def-hilbert-space",
            "def-orthogonality-and-orthogonal-complement",
            "def-real-and-complex-inner-product-space",
            "lem-pythagorean-theorem-and-finite-orthogonal-sums",
            "thm-metric-closure-characterisation",
            "thm-orthogonal-decomposition-by-a-closed-subspace"
          ],
          "dependency_level": 0,
          "proof_strategy": "direct",
          "provenance": {
            "statement": "literature-derived",
            "proof": "ai-altered"
          },
          "sources": {
            "references": [
              {
                "title": "Christian Clason, Regularization of Inverse Problems: Lecture Notes, arXiv:2001.00617v2, Theorem 3.3",
                "url": "https://arxiv.org/pdf/2001.00617"
              },
              {
                "title": "Otmar Scherzer and Leonidas Mindrinos, Inverse Problems: Lecture Notes, University of Vienna, 2015",
                "url": "https://www.csc.univie.ac.at/files/InverseProblems_SS15/InverseProblems_full.pdf"
              }
            ]
          },
          "statement": "Assume the Axiom of Countable Choice. Let $X$ and $Y$ be real or complex Hilbert\nspaces over the same scalar field, and let $K:X\\to Y$ be a bounded linear\noperator. Write $R(K):=\\{Kx:x\\in X\\}$ for its range,\n$N(K):=\\{x\\in X:Kx=0\\}$ for its kernel, and\n$M^\\perp:=\\{z:\\langle z,m\\rangle=0\\text{ for every }m\\in M\\}$ for the\northogonal complement of a subspace $M$. The kernel $N(K)$ is closed, so the\nrestriction\n$$\\widetilde K:=K|_{N(K)^\\perp}:N(K)^\\perp\\to R(K)$$\nis a linear bijection. Define the Hilbert-space Moore–Penrose inverse $K^\\dagger$\nto have domain\n$$D(K^\\dagger):=R(K)\\oplus R(K)^\\perp$$\nand, for the unique decomposition $y=r+z$ with $r\\in R(K)$ and\n$z\\in R(K)^\\perp$, set\n$$K^\\dagger y:=\\widetilde K^{-1}r.$$\nThus $K^\\dagger y$ is the unique minimum-norm solution of $Kx=r$, and the\northogonal-range component is mapped to zero. Boundedness of $K^\\dagger$ on\nthis domain is not part of the definition."
        },
        {
          "id": "def-ip-compact-linear-inverse-model",
          "kind": "definition",
          "title": "Compact linear inverse model between Hilbert spaces",
          "deps": [
            "def-compact-linear-operator",
            "def-hilbert-space",
            "def-ip-forward-map-and-solution-classes"
          ],
          "dependency_level": 1,
          "provenance": {
            "statement": "literature-derived",
            "proof": "not-applicable"
          },
          "sources": {
            "references": [
              {
                "title": "Christian Clason, Regularization of Inverse Problems: Lecture Notes, arXiv:2001.00617v2, §3.1",
                "url": "https://arxiv.org/pdf/2001.00617"
              },
              {
                "title": "Otmar Scherzer and Leonidas Mindrinos, Inverse Problems: Lecture Notes, University of Vienna, 2015",
                "url": "https://www.csc.univie.ac.at/files/InverseProblems_SS15/InverseProblems_full.pdf"
              }
            ]
          },
          "statement": "Let $X,Y$ be real or complex Hilbert spaces over the same scalar field, and let\n$K:X\\to Y$ be a compact linear operator. The associated compact linear inverse\nmodel has parameter space $X$, data space $Y$, forward map $K$, and admissible\ntruth class $X$: for a true parameter $x^\\dagger\\in X$, the exact datum is\n$y=Kx^\\dagger\\in Y$. Given an exact datum $y\\in Y$, solving this inverse\nproblem means finding a parameter $x\\in X$ such that $Kx=y$. No injectivity,\nsurjectivity, or closed-range assumption is included in the model."
        },
        {
          "id": "thm-ip-closed-range-pseudoinverse-stability",
          "kind": "theorem",
          "title": "Closed range and boundedness of the Hilbert pseudoinverse",
          "deps": [
            "cor-archimedean-reciprocal",
            "cor-finite-dimensional-subspaces-are-closed",
            "def-countable-choice",
            "def-hilbert-space",
            "def-hilbert-space-adjoint",
            "def-ip-compact-linear-inverse-model",
            "def-ip-unbounded-hilbert-moore-penrose-inverse",
            "lem-finite-bessel-inequality",
            "lem-pythagorean-theorem-and-finite-orthogonal-sums",
            "thm-recursion",
            "thm-cauchy-schwarz-in-an-inner-product-space",
            "thm-well-ordering-principle",
            "thm-singular-value-decomposition-for-compact-operators"
          ],
          "dependency_level": 2,
          "proof_strategy": "direct",
          "provenance": {
            "statement": "literature-derived",
            "proof": "ai-altered"
          },
          "sources": {
            "references": [
              {
                "title": "Christian Clason, Regularization of Inverse Problems: Lecture Notes, arXiv:2001.00617v2, Theorem 3.7",
                "url": "https://arxiv.org/pdf/2001.00617"
              },
              {
                "title": "Otmar Scherzer and Leonidas Mindrinos, Inverse Problems: Lecture Notes, University of Vienna, 2015, Theorem 6.6 (singular-system context)",
                "url": "https://www.csc.univie.ac.at/files/InverseProblems_SS15/InverseProblems_full.pdf"
              }
            ]
          },
          "statement": "Assume the Axiom of Countable Choice. Let $K:X\\to Y$ be the compact linear\noperator of a real or complex Hilbert-space inverse model, and let\n$K^\\dagger:D(K^\\dagger)\\to X$ be its Hilbert-space Moore–Penrose inverse, with\n$D(K^\\dagger)=R(K)\\oplus R(K)^\\perp$ carrying the norm inherited from $Y$.\nThen $K^\\dagger$ is bounded on its domain if and only if $R(K)$ is closed in\n$Y$; for compact $K$, these conditions are also equivalent to $R(K)$ being\nfinite-dimensional. Here bounded means that some real $C\\ge0$ satisfies\n$\\|K^\\dagger y\\|_X\\le C\\|y\\|_Y$ for every $y\\in D(K^\\dagger)$."
        },
        {
          "id": "thm-ip-picard-range-criterion-for-compact-operators",
          "kind": "theorem",
          "title": "Picard range and pseudoinverse-domain criterion",
          "deps": [
            "def-compact-linear-operator",
            "def-countable-choice",
            "def-hilbert-space",
            "def-hilbert-space-adjoint",
            "def-ip-compact-linear-inverse-model",
            "def-ip-unbounded-hilbert-moore-penrose-inverse",
            "def-real-and-complex-inner-product-space",
            "lem-finite-bessel-inequality",
            "lem-kernel-range-orthogonality-for-hilbert-adjoints",
            "lem-pythagorean-theorem-and-finite-orthogonal-sums",
            "thm-cauchy-schwarz-in-an-inner-product-space",
            "thm-hilbert-space-fourier-expansion",
            "thm-orthogonal-decomposition-by-a-closed-subspace",
            "thm-singular-value-decomposition-for-compact-operators"
          ],
          "dependency_level": 2,
          "proof_strategy": "direct",
          "provenance": {
            "statement": "literature-derived",
            "proof": "ai-altered"
          },
          "sources": {
            "references": [
              {
                "title": "Christian Clason, Regularization of Inverse Problems: Lecture Notes, arXiv:2001.00617v2, Theorem 3.10",
                "url": "https://arxiv.org/pdf/2001.00617"
              },
              {
                "title": "Otmar Scherzer and Leonidas Mindrinos, Inverse Problems: Lecture Notes, University of Vienna, 2015, Theorem 6.7",
                "url": "https://www.csc.univie.ac.at/files/InverseProblems_SS15/InverseProblems_full.pdf"
              },
              {
                "title": "Vesa Kaarnioja, Inverse Problems: Fourth Lecture, FU Berlin, 8 May 2023",
                "url": "https://vkaarnioja.github.io/ip23/week4.pdf"
              }
            ]
          },
          "statement": "Assume the Axiom of Countable Choice. Let $K:X\\to Y$ be a compact linear map\nbetween real or complex Hilbert spaces, with Hilbert adjoint $K^*:Y\\to X$.\nWrite $\\mathbb N_{>0}:=\\{1,2,3,\\ldots\\}$. If $R(K)$ has finite dimension\n$r\\in\\mathbb N$, put $J=\\{1,\\ldots,r\\}$, interpreted as empty when $r=0$;\nif $R(K)$ is infinite-dimensional, put $J=\\mathbb N_{>0}$. Thus $J$ indexes\nexactly the positive singular values $s_j>0$ in nonincreasing order. Let\n$(v_j)_{j\\in J}$ and $(u_j)_{j\\in J}$ be complete\northonormal families in $N(K)^\\perp$ and $\\overline{R(K)}$, respectively,\nwith $Kv_j=s_ju_j$ and $K^*u_j=s_jv_j$. The empty sum is zero, finite $J$\nuses a finite sum, and infinite $J$ uses the norm-convergent series whenever\nthe stated square-summability condition holds. Use inner products linear in the\nfirst argument. Define the Picard sum\n$$P_K(y):=\\sum_{j\\in J}\\frac{|\\langle y,u_j\\rangle_Y|^2}{s_j^2},\\qquad y\\in Y.$$\nThen:\n\n1. The exact equation $Kx=y$ is solvable if and only if\n   $y\\perp N(K^*)$ and $P_K(y)<\\infty$.\n\n2. The domain of the Hilbert-space Moore–Penrose inverse is\n   $$D(K^\\dagger)=R(K)\\oplus R(K)^\\perp=\\{y\\in Y:P_K(y)<\\infty\\},$$\n   and for every $y\\in D(K^\\dagger)$,\n   $$K^\\dagger y=\\sum_{j\\in J}\\frac{\\langle y,u_j\\rangle_Y}{s_j}v_j.$$\n   Thus the orthogonal component in $R(K)^\\perp=N(K^*)$ is discarded by\n   $K^\\dagger$; exact range membership additionally requires that component\n   to be zero."
        }
      ]
    }

