      "items": [
        {
          "id": "def-ip-noise-level-free-parameter-rule",
          "kind": "definition",
          "title": "Noise-level-free parameter-choice rule",
          "statement": "Fix a compact Hilbert inverse model $K:X\\to Y$ and a family of reconstruction\nmaps $(R_\\alpha)_{\\alpha>0}$, with each $R_\\alpha:Y\\to X$, both held fixed. A\ndeterministic parameter-choice rule is a function\n$\\alpha:Y\\to(0,\\infty)$. It is **noise-level-free** (also called **heuristic**)\nwhen the value $\\alpha(z)$ for an observed datum $z\\in Y$ uses only $K$, the\nfixed family, and $z$; it does not take the exact datum or a noise bound\n$\\delta$ as input. Here $\\delta\\ge0$ is a valid noise bound for $z$ and an\nexact datum $y$ when $\\|z-y\\|_Y\\le\\delta$. The resulting reconstruction is\n$R_{\\alpha(z)}z$.",
          "deps": [
            "def-ip-compact-linear-inverse-model"
          ],
          "dependency_level": 2,
          "provenance": {
            "statement": "literature-derived",
            "proof": "not-applicable"
          },
          "sources": {
            "references": [
              {
                "title": "Christian Clason, Regularization of Inverse Problems: Lecture Notes, Definition 4.4",
                "url": "https://imsc.uni-graz.at/clason/preprints/InverseNotes.pdf",
                "locator": "Chapter 4, Definition 4.4, PDF p. 34; categories of parameter-choice rules."
              },
              {
                "title": "Ferdia Sherry, Inverse Problems: Lecture Notes 2024, Section 3.2.3",
                "url": "https://ferdiasherry.com/LectureNotes2024.pdf",
                "locator": "Section 3.2.3, PDF pp. 33–34; heuristic parameter rules and Theorem 3.12."
              }
            ]
          }
        },
        {
          "id": "thm-ip-bakushinskii-veto",
          "kind": "theorem",
          "title": "Bakushinskii veto for discontinuous pseudoinverses",
          "statement": "Assume Countable Choice. Let $K:X\\to Y$ be a compact linear operator between\nreal or complex Hilbert spaces over one scalar field, with Hilbert-space\nMoore–Penrose inverse $K^\\dagger:D(K^\\dagger)\\to X$. Suppose $K^\\dagger$ is\ndiscontinuous on $D(K^\\dagger)$ with its norm inherited from $Y$. Let\n$(R_\\alpha)_{\\alpha>0}$ be maps $Y\\to X$ such that\n$R_\\alpha y\\to K^\\dagger y$ for every $y\\in D(K^\\dagger)$ as\n$\\alpha\\downarrow0$, and let $\\alpha:Y\\to(0,\\infty)$ be a deterministic\nnoise-level-free rule. For each exact datum $y\\in D(K^\\dagger)$ and\n$\\delta>0$, set $E_y(\\delta):=\\sup\\{\\|R_{\\alpha(z)}z-K^\\dagger y\\|_X:z\\in Y,\\ \\|z-y\\|_Y\\le\\delta\\}$.\nIf $E_y(\\delta)\\to0$ as $\\delta\\downarrow0$ for every $y\\in D(K^\\dagger)$,\nthen $K^\\dagger$ is continuous on $D(K^\\dagger).$ Thus, when $K^\\dagger$ is\ndiscontinuous, no such noise-level-free rule yields worst-case convergence\nover each exact datum's full admissible error balls. The limit is required\nseparately for each exact datum, not uniformly over $y$. This veto does not\nexclude convergence on restricted solution or error classes, stochastic noise\nmodels, or finite-dimensional problems.",
          "deps": [
            "def-countable-choice",
            "def-ip-compact-linear-inverse-model",
            "def-ip-noise-level-free-parameter-rule",
            "def-ip-unbounded-hilbert-moore-penrose-inverse"
          ],
