          },
          "dependency_level": 0,
          "proof_strategy": "direct"
        },
        {
          "id": "lem-ip-vector-radon-variation-is-radon",
          "kind": "lemma",
          "title": "Variation of a finite vector Radon measure is Radon",
          "deps": [
            "def-radon-measure-on-an-lch-space",
            "def-regular-borel-measure-on-an-lch-space",
            "def-regular-complex-borel-measure-on-an-lch-space",
            "thm-total-variation-is-a-measure"
          ],
          "statement": "Let $\\Omega\\subseteq\\mathbb R^n$ be open and let $\\mu=(\\mu_1,\\ldots,\\mu_m)$ have finite signed Radon coordinate measures. For Borel $A\\subseteq\\Omega$ define $$V(A):=\\sup\\left\\{\\sum_{j=1}^\\infty |\\mu(A_j)|:(A_j)_{j\\ge1}\\text{ is a Borel partition of }A\\right\\},$$ where the norm is Euclidean. Then $V$ is a finite positive Radon measure and $$V(\\Omega)=\\sup\\left\\{\\int_\\Omega f\\cdot d\\mu:f\\in C_c(\\Omega;\\mathbb R^m),\\ |f(x)|\\le1\\right\\}.$$",
          "sources": {
            "references": [
              {
                "title": "Gláucio Terra, Introduction to Geometric Measure Theory — Lecture Notes, version 1.6",
                "url": "https://www.ime.usp.br/~glaucio/mat6704/textos/GMTLecureNotes.pdf"
              }
            ]
          },
          "provenance": {
            "statement": "literature-derived",
            "proof": "ai-altered"
          },
          "dependency_level": 0,
          "proof_strategy": "direct"
        },
        {
          "id": "lem-ip-open-euclidean-locally-finite-smooth-partition",
          "kind": "lemma",
          "title": "Locally finite smooth partitions of unity on Euclidean open sets",
          "deps": [
            "lem-rat-embeds-dense",
            "lem-smooth-bump-between-concentric-euclidean-balls",
            "thm-heine-borel-rn",
            "thm-product-of-countable",
            "thm-rationals-countable"
          ],
          "statement": "If an open set $\\Omega\\subseteq\\mathbb R^n$ is covered by a countable family of open sets $(V_\\ell)_{\\ell\\in I}$, then there is a countable locally finite family of nonnegative functions $(\\eta_j)\\subset C_c^\\infty(\\Omega)$ summing to one, with each $\\operatorname{supp}\\eta_j$ contained in one member $V_\\ell$ of the cover. Locally finite means that each point has a neighborhood meeting only finitely many supports.",
          "sources": {
            "references": [
              {
                "title": "Gláucio Terra, Introduction to Geometric Measure Theory — Lecture Notes, version 1.6",
                "url": "https://www.ime.usp.br/~glaucio/mat6704/textos/GMTLecureNotes.pdf"
