        {
          "id": "lem-ip-l1-sequence-compactness-by-cell-averages",
          "kind": "lemma",
          "title": "Sequence compactness in L1 by finite cell averages",
          "deps": [
            "def-countable-choice",
            "thm-tonelli-and-fubini-for-completed-product-measures",
            "thm-euclidean-lebesgue-measure-is-the-completion-of-the-product-of-lebesgue-measures",
            "def-l-p-space-as-a-quotient-by-null-functions",
            "thm-tonelli-theorem-for-sigma-finite-product-spaces",
            "thm-lebesgue-outer-measure-and-measurability-are-translation-invariant",
            "thm-recursion"
          ],
          "proof_strategy": "direct",
          "provenance": {
            "statement": "literature-derived",
            "proof": "ai-altered"
          },
          "sources": {
            "references": [
              {
                "title": "Glaucio Terra, Introduction to Geometric Measure Theory, Theorems 1.80 and 7.49",
                "url": "https://www.ime.usp.br/~glaucio/mat6704/textos/GMTLecureNotes.pdf"
              }
            ]
          },
          "statement": "Assume Countable Choice. Let $(v_k)$ be a sequence in real $L^1(\\mathbb R^n)$, with $\\sup_k\\|v_k\\|_1<\\infty$, all zero almost everywhere outside one bounded set. If $\\lim_{r\\downarrow0}\\sup_{k,\\ |h|\\le r}\\|v_k(\\cdot+h)-v_k\\|_1=0$, then a subsequence converges in $L^1(\\mathbb R^n)$. This assertion does not require Dependent Choice.",
          "dependency_level": 0
        },
        {
          "id": "lem-ip-lipschitz-graph-area-and-calculus-under-countable-choice",
          "kind": "lemma",
          "title": "Lipschitz graph area and calculus under Countable Choice",
          "deps": [
            "def-countable-choice",
            "thm-dominated-convergence",
            "thm-monotone-convergence-for-the-integral",
            "thm-c1-lipschitz-ac-bv-hierarchy",
            "thm-absolutely-continuous-functions-have-integrable-derivatives",
            "thm-tonelli-and-fubini-for-completed-product-measures",
            "thm-euclidean-lebesgue-measure-is-the-completion-of-the-product-of-lebesgue-measures",
            "thm-lebesgue-differentiation-theorem-for-locally-integrable-functions-on-r-n",
            "thm-linear-change-of-variables-for-lebesgue-measure",
            "thm-hausdorff-n-measure-is-proportional-to-lebesgue-measure",
            "thm-hausdorff-measure-under-lipschitz-maps",
            "cor-hausdorff-measure-under-similarities"
          ],
          "proof_strategy": "direct",
          "provenance": {
            "statement": "literature-derived",
            "proof": "ai-altered"
          },
          "sources": {
            "references": [
              {
                "title": "Glaucio Terra, Introduction to Geometric Measure Theory, Rademacher Section 5.1.2 and area Section 5.2",
                "url": "https://www.ime.usp.br/~glaucio/mat6704/textos/GMTLecureNotes.pdf"
              }
            ]
          },
          "statement": "Assume Countable Choice. Let $m\\ge1$, let $Q\\subseteq\\mathbb R^m$ be open, and let $h:Q\\to\\mathbb R$ be locally Lipschitz. Then $h$ is differentiable almost everywhere, its partial derivatives are measurable and are its weak derivatives. On every open region where $h$ is $L$-Lipschitz, $|Dh|\\le L$ almost everywhere. Let $H^m$ denote the repository's unnormalised Hausdorff measure, put $c_m=H^m((0,1]^m)$, and write $\\sigma_m=c_m^{-1}H^m$ also on Euclidean spaces containing $m$-dimensional subsets. The graph map $F(y)=(y,h(y))$ satisfies, for every nonnegative Borel $a$,\n$$\\int_{F(Q)}a(x)\\,d\\sigma_m(x)=\\int_Qa(F(y))\\sqrt{1+|Dh(y)|^2}\\,dy.$$\nFor the epigraph $G=\\{(y,z):y\\in Q,\\ z>h(y)\\}$, a smooth vector field compactly supported away from the chart sides satisfies\n$$\\int_G\\operatorname{div}\\phi\\,dx=\\int_Q\\phi(y,h(y))\\cdot(Dh(y),-1)\\,dy.$$\nThus its outward normal is $(Dh,-1)/\\sqrt{1+|Dh|^2}$ almost everywhere. The sign reverses for a subgraph. The graph surface measure is locally finite and Radon on $F(Q)$ with its relative topology, and its null sets coincide with graph images of Lebesgue-null subsets of the base.",
          "dependency_level": 0
        },
        {
          "id": "def-ip-spatial-bv-and-distributional-tv",
          "kind": "definition",
          "title": "Spatial BV and distributional total variation",
          "deps": [
            "def-distributional-derivative",
            "def-l-p-space-as-a-quotient-by-null-functions",
            "def-radon-measure-on-an-lch-space",
            "def-regular-complex-borel-measure-on-an-lch-space",
            "lem-ip-distributional-radon-representation-unique",
            "lem-ip-vector-radon-variation-is-radon"
          ],
          "statement": "Let $\\Omega\\subseteq\\mathbb R^n$ be open and let $u\\in L^1(\\Omega;\\mathbb R)$, where elements of $L^1$ are almost-everywhere equivalence classes. For each $i\\in\\{1,\\ldots,n\\}$, its distributional derivative $D_i u$ acts on $\\varphi\\in C_c^\\infty(\\Omega)$ by\n$$\\langle D_i u,\\varphi\\rangle:=-\\int_\\Omega u\\,\\partial_i\\varphi\\,dx.$$\nThe function $u$ is in $BV(\\Omega)$ when each $D_i u$ is represented by a finite signed Radon measure and the resulting vector-valued measure $Du=(D_1u,\\ldots,D_nu)$ has finite total variation. Here a finite vector-valued Radon measure means that its partition variation is a finite Radon measure. For a Borel set $A\\subseteq\\Omega$, define\n$$|Du|(A):=\\sup\\left\\{\\sum_{j=1}^\\infty |Du(A_j)|:\\ (A_j)_{j\\ge1}\\text{ is a Borel partition of }A\\right\\},$$\nusing the Euclidean norm on each vector value. Define the spatial total variation by $TV(u;\\Omega):=|Du|(\\Omega)$. A Lebesgue-measurable set $E\\subseteq\\Omega$ of finite measure has finite perimeter relative to $\\Omega$ when $\\chi_E\\in BV(\\Omega)$; its relative perimeter is $P(E;\\Omega):=TV(\\chi_E;\\Omega)$.",
          "sources": {
            "references": [
              {
                "title": "Gláucio Terra, Introduction to Geometric Measure Theory — Lecture Notes, version 1.6",
                "url": "https://www.ime.usp.br/~glaucio/mat6704/textos/GMTLecureNotes.pdf"
              },
              {
                "title": "Piotr Rybka, The space in variational and evolution problems — Lecture Notes in Mathematical Sciences 15",
                "url": "https://www.ms.u-tokyo.ac.jp/publication/docs/lecturenotes15-rybka.pdf"
              }
            ]
          },
          "provenance": {
            "statement": "literature-derived",
            "proof": "not-applicable"
          },
          "dependency_level": 1
        },
        {
          "id": "lem-ip-unit-vector-density-has-scalar-variation",
          "kind": "lemma",
          "title": "A unit vector density has scalar variation measure",
          "deps": [
            "lem-ip-vector-radon-variation-is-radon",
            "def-radon-measure-on-an-lch-space",
            "def-regular-complex-borel-measure-on-an-lch-space",
            "thm-dominated-convergence",
            "thm-total-variation-is-a-measure"
          ],
          "statement": "Let $X$ be a locally compact second-countable metric space, let $\\lambda$ be a finite positive Radon measure on $X$, and let $\\nu:X\\to\\mathbb R^m$ be continuous with $|\\nu(x)|=1$ for every $x$. Define the vector measure $\\mu(A):=\\int_A\\nu\\,d\\lambda$ on Borel sets. Its partition variation satisfies $|\\mu|=\\lambda$.",
          "sources": {
            "references": [
              {
                "title": "Gláucio Terra, Introduction to Geometric Measure Theory — Lecture Notes, version 1.6",
                "url": "https://www.ime.usp.br/~glaucio/mat6704/textos/GMTLecureNotes.pdf"
