          },
          "sources": {
            "references": [
              {
                "title": "Donald L. Cohn, Measure Theory, second edition, Chapter 7",
                "url": "https://math.bme.hu/~pitrik/2023_24_2/Measure_Cohn.pdf"
              }
            ]
          },
          "statement": "Assume Countable Choice. For every open $U\\subseteq\\mathbb R^d$, every bounded real linear functional on $C_0(U;\\mathbb R)$ is integration against a unique finite signed Radon measure. No Dependent Choice assumption is required.",
          "dependency_level": 1
        },
        {
          "id": "lem-ip-bv-test-field-characterization-and-lsc",
          "kind": "lemma",
          "title": "Test-field formula and L1 lower semicontinuity of spatial TV",
          "deps": [
            "def-ip-spatial-bv-and-distributional-tv",
            "def-compact-support-c-c-and-c-zero-on-an-lch-space",
            "lem-ip-vector-radon-variation-is-radon",
            "lem-ip-smooth-compact-support-dense-in-c0",
            "lem-ip-euclidean-radon-representation-under-countable-choice",
            "def-countable-choice"
          ],
          "statement": "For every open $\\Omega\\subseteq\\mathbb R^n$ and real-valued $u\\in BV(\\Omega)$, $$TV(u;\\Omega)=\\sup\\left\\{\\int_\\Omega u\\,\\operatorname{div}\\varphi\\,dx:\\varphi\\in C_c^\\infty(\\Omega;\\mathbb R^n),\\ |\\varphi(x)|\\le1\\right\\}.$$ If $u_k,u\\in BV(\\Omega)$ are real-valued and $u_k\\to u$ in $L^1(\\Omega)$, then $TV(u;\\Omega)\\le\\liminf_kTV(u_k;\\Omega)$. In addition, assuming Countable Choice, for any real-valued $u\\in L^1(\\Omega)$ the displayed supremum is finite if and only if $u\\in BV(\\Omega)$, with equality to $TV(u;\\Omega)$; under the same assumption, an $L^1$ limit of real-valued BV functions with bounded liminf total variation belongs to $BV(\\Omega)$ and satisfies the same lower-semicontinuity inequality.",
          "sources": {
            "references": [
              {
                "title": "Gláucio Terra, Introduction to Geometric Measure Theory — Lecture Notes, version 1.6",
                "url": "https://www.ime.usp.br/~glaucio/mat6704/textos/GMTLecureNotes.pdf"
              },
              {
                "title": "Piotr Rybka, The space in variational and evolution problems — Lecture Notes in Mathematical Sciences 15",
                "url": "https://www.ms.u-tokyo.ac.jp/publication/docs/lecturenotes15-rybka.pdf"
              }
            ]
          },
          "provenance": {
