        {
          "id": "lem-kauffman-bracket-curl-and-writhe-correction",
          "kind": "lemma",
          "title": "Kauffman bracket curl and writhe correction",
          "deps": [
            "def-kauffman-bracket-smoothing-and-loop-value",
