          "sources": {
            "references": [
              {
                "title": "Introduction to Vassiliev Knot Invariants, §§8.2 and 8.6",
                "url": "https://www.math.cinvestav.mx/~mostovoy/cdbook/cdbook-as-submitted.pdf"
              },
