        {
          "id": "thm-conway-second-coefficient-is-type-two",
          "kind": "theorem",
          "title": "The second Conway coefficient is a degree-two finite-type invariant",
          "deps": [
            "def-kontsevich-integral-on-parenthesized-braids",
            "def-conway-polynomial",
