          "sources": {
            "references": [
              {
                "title": "Introduction to Vassiliev Knot Invariants, §§2.3 and 3.1.1",
                "url": "https://www.math.cinvestav.mx/~mostovoy/cdbook/cdbook-as-submitted.pdf"
              },
