          "id": "def-odd-khovanov-barnatan-and-leo-triple",
          "kind": "definition",
          "title": "Odd Khovanov–Bar–Natan–LEO triple",
          "deps": [],
          "dependency_level": 0,
          "provenance": {
            "statement": "literature-derived",
            "proof": "ai-altered"
