          "kind": "lemma",
          "title": "A crossing-ball cover of a knot complement",
          "deps": [
            "def-knot-planar-code",
            "lem-compact-knot-has-choice-free-tube",
            "def-oriented-link-in-s-three-and-ambient-isotopy",
