              {
                "title": "Andras Juhasz, Holomorphic discs and sutured manifolds, §4",
                "url": "https://msp.org/agt/2006/6-3/agt-v6-n3-p16-s.pdf",
                "locator": "Printed pp.1441–1442, connected-manifold convention and Definition 4.2; applied componentwise here"
              },
