        {
          "id": "def-singular-instanton-knot-and-sutured-closure-data",
          "kind": "definition",
          "title": "Singular instanton knot and sutured closure data",
          "deps": [
            "def-knot-exterior",
            "def-knot-meridian-and-preferred-longitude",
